    out = bytearray()
    for char in text:
        cp = ord(char)
        if 0xFE00 <= cp <= 0xFE0F:
            out.append(cp - 0xFE00)
        elif 0xE0100 <= cp <= 0xE01EF:
            out.append(cp - 0xE0100 + 0x10)
    return bytes(out)


