        idx = raw.find(magic)
        while idx != -1:
            add(raw[idx:])
            idx = raw.find(magic, idx + 1)

    for marker in (b"FRV2",):
        idx = raw.find(marker)
        while idx != -1:
            tail = raw[idx + len(marker):]
            add(tail)
            gzip_idx = tail.find(b"\x1f\x8b")
            if gzip_idx != -1:
                add(tail[gzip_idx:])
            idx = raw.find(marker, idx + 1)

    return payloads


def try_gzip(data: bytes) -> bytes | None:
    try:
        return gzip.decompress(data)
    except Exception:
        return None


def try_zlib(data: bytes) -> bytes | None:
    for wbits in (zlib.MAX_WBITS, -zlib.MAX_WBITS, zlib.MAX_WBITS | 16, zlib.MAX_WBITS | 32):
        try:
            return zlib.decompress(data, wbits)
        except Exception:
            continue
    return None


def try_streaming_gzip(data: bytes) -> bytes | None:
    try:
        with gzip.GzipFile(fileobj=io.BytesIO(data), mode="rb") as gz:
            return gz.read()
    except Exception:
        return None


def decompress_payload(raw: bytes) -> bytes:
    attempts = []
    for payload in candidate_payloads(raw):
        attempts.append(payload)
    for payload in attempts:
        result = try_gzip(payload)
        if result is not None:
            return result
        result = try_streaming_gzip(payload)
        if result is not None:
            return result
        result = try_zlib(payload)
        if result is not None:
            return result
    raise ValueError("Nem sikerült érvényes GZIP vagy zlib adatot találni a kinyert bájtok között.")


def is_probably_text(data: bytes) -> tuple[bool, str | None]:
    encodings = ("utf-8", "utf-8-sig", "utf-16", "utf-16-le", "utf-16-be")
    for encoding in encodings:
        try:
            return True, data.decode(encoding)
        except UnicodeDecodeError:
            continue
    return False, None


def main() -> int:
