    text = input_path.read_text(encoding="utf-8")
    raw_bytes = extract_variation_selector_bytes(text)

    if not raw_bytes:
        raise ValueError("A bemeneti fájl nem tartalmaz dekódolható változatválasztó karaktereket.")

    decompressed = decompress_payload(raw_bytes)
    is_text, decoded = is_probably_text(decompressed)

    if is_text and decoded is not None:
        sys.stdout.write(decoded)
        if decoded and not decoded.endswith("\n"):
            sys.stdout.write("\n")
    else:
        Path(BINARY_OUTPUT).write_bytes(decompressed)
        sys.stdout.write(f"Bináris fájl, elmentve: {BINARY_OUTPUT}\n")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
